/**
 * Image registry contract.
 *
 * `content/photos.ts` is GENERATED by `scripts/process-photos.mjs` from
 * `scripts/photo-manifest.json` + `scripts/photos/*.json`. Edit those (crops,
 * ROIs, alt text, credits) and re-run `npm run photos` — never hand-edit photos.ts.
 *
 * Coordinates: every box/point is a fraction (0..1) of the FULL processed
 * image, origin top-left. components/Scene.tsx maps them into any
 * cover-cropped container with pure CSS, so overlays stay locked to the
 * photograph at every size.
 */

/** thermal = pre-rendered heat overlay (only where a thermal source is plausible)
 *  outline = brackets + faint amber wash (state detections: gate open, obstruction)
 *  data    = selection highlight for records, labels, fields
 *  frame   = brackets only — the infrared is already painted into an AI-generated image */
export type RoiKind = "thermal" | "outline" | "data" | "frame";

export type Roi = {
  /** stable key, unique within the photo, e.g. "bearing" */
  key: string;
  /** [x, y, w, h] as fractions of the full image */
  box: [number, number, number, number];
  kind: RoiKind;
  /** public path to the RGBA overlay cropped exactly to `box` (thermal only) */
  overlay?: string;
  /** what physically sits in the region, e.g. "Ring bearing housing" */
  subject: string;
  /** a plausible, qualitative observation for this region, e.g. "Abnormal operating pattern" */
  suggestion: string;
};

export type PhotoSource = string;

export type Photo = {
  slug: string;
  /** "/img/photo/<slug>.jpg" */
  src: string;
  /** "/img/thumb/<slug>.jpg", 960 px wide */
  thumb?: string;
  width: number;
  height: number;
  /** meaningful alt text describing the scene (not "image of") */
  alt: string;
  category?: number;
  /** short human description, e.g. "Riveted turbine casing in a brick hall" */
  subject: string;
  /** overall brightness — helps decide text-on-photo and fade colour */
  tone: "light" | "mid" | "dark";
  /** recommended object-position [x, y] fractions for cover crops */
  focal: [number, number];
  /** calm areas of the frame that can take a fade or text */
  quiet?: Array<"left" | "right" | "top" | "bottom">;
  rois: Roi[];
  credit: {
    author: string;
    authorUrl?: string;
    source: PhotoSource;
    url: string;
    license: string;
    licenseUrl?: string;
  };
  /** people visible in frame */
  people: "none" | "non-identifiable" | "blurred" | "identifiable";
  /** free tags for picking: "night", "fog", "interior", "texture", "drawing", "portrait" … */
  tags: string[];
};
